func:
// Heating config: the ONLY place with installation-specific IDs.
// Runs on deploy. Every heating function reads global "heatingCfg".
global.set('heatingCfg', {
    ent: {
        room: 'sensor.room_temperature',            // master room temperature
        roomHumidity: 'sensor.room_humidity', // same sensor: its updates also prove the sensor is alive
        outdoor: 'sensor.outdoor_temperature',      // outdoor temperature (Met Office)
        relay: 'switch.heating_relay',          // Shelly relay across boiler terminals 3-4
        nextAlarms: ['sensor.phone_next_alarm'],  // phone "next alarm" sensors: the earliest today wins
        alarmCal: 'calendar.alarm',    // calendar: an entry = no alarm that day
    },
    shellyTopic: '<SHELLY_MQTT_PREFIX>',  // Shelly MQTT topic prefix (RPC on <prefix>/rpc)
    notifyAll: ['notify.<NOTIFY_SERVICE>'],        // alerts
    notifyOwner: 'notify.<NOTIFY_SERVICE>',  // promotion approvals
    flowMax: 60,                     // boiler panel flow setting = hard ceiling
    hwcTemp: 50,                     // boiler hot-water setting, sent in every SetMode
    ebusPrefix: 'ebusd/bai',
    // eBUS writes stay off until the Stage 1 checkpoint has verified the
    // SetMode payload on this boiler. ebusd itself is also read-only until then.
    ebusWriteEnabled: false,
});
node.status({ fill: 'green', shape: 'dot', text: 'config loaded' });
return null;

// Ask ebusd for fresh values every minute (read requests only).
// ebusd only auto-polls values it has already seen, so this keeps them current.
const cfg = global.get('heatingCfg');
if (!cfg) return null;
const names = ['FlowTemp', 'ReturnTemp', 'FlowTempDesired', 'Flame',
    'ModulationDesired', 'DCRoomthermostat', 'HwcDemand', 'HwcImpellorSwitch'];
return [names.map(n => ({ topic: `${cfg.ebusPrefix}/${n}/get`, payload: '' }))];

// Keep the latest value of each ebusd message (flow context, memory).
// --mqttjson payloads look like {"temp":{"value":60.1},"sensor":{"value":"ok"}}.
const name = msg.topic.split('/').pop();
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { /* plain value */ } }
let v = p;
if (p && typeof p === 'object') {
    const key = ['temp', 'value', 'press'].find(k => k in p) || Object.keys(p)[0];
    v = p[key];
    if (v && typeof v === 'object' && 'value' in v) v = v.value;
}
const ebus = flow.get('ebus') || {};
ebus[name] = { v, ts: Date.now() };
flow.set('ebus', ebus);
node.status({ text: `${name} = ${v}` });
return null;

// Heating control loop, every 60 s.
//   flow  = set + slope*(set - outdoor) + offset + Kp*err + I    (err = set - room)
//   final = clamp(flow, stage_floor, 60)
// Outputs: 1 = HA service calls, 2 = eBUS SetMode (MQTT), 3 = comfort event.
// input_boolean.heating_live off = dry-run: everything is calculated and written to
// the heating helpers, but the relay is never switched and nothing goes to eBUS.

const cfg = global.get('heatingCfg');
const ha = global.get('homeassistant');
const states = ha && ha.homeAssistant && ha.homeAssistant.states;
if (!cfg || !states) { node.status({ fill: 'red', shape: 'ring', text: 'waiting for HA/config' }); return null; }

const S = id => (states[id] ? states[id].state : undefined);
const N = id => { const v = parseFloat(S(id)); return isFinite(v) ? v : null; };
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const r1 = v => Math.round(v * 10) / 10;
const r2 = v => Math.round(v * 100) / 100;
const tmin = (id, dflt) => { const s = S(id); if (!s || !s.includes(':')) return dflt; const [h, m] = s.split(':').map(Number); return h * 60 + m; };

// Fixed rules (documented in the public guide)
const HYST = 0.2;               // relay on below set-0.2, off above set+0.2
const ROOM_STALE_MIN = 90;      // no room sensor update for this long = no room sensor
                                // (HA only updates on a change, so a steady room is quiet)
const GUARD_BELOW = 1.0;        // comfort guard: this far below set...
const GUARD_MIN = 30;           // ...for this many minutes
const GUARD_RELEASE = 0.3;      // released when within this of set
const RESEND_MS = 4 * 60000;    // re-send SetMode every 4 min
const RELAY_RESEND_MS = 5 * 60000; // re-send the relay state every 5 min

const now = new Date(), nowMs = now.getTime();
const minOfDay = now.getHours() * 60 + now.getMinutes();
const weekend = now.getDay() === 0 || now.getDay() === 6;
const dkey = `${now.getFullYear()}-${now.getMonth() + 1}-${now.getDate()}`;

// --- Helpers ---
const live = S('input_boolean.heating_live') === 'on';
const stage = parseInt(String(S('input_select.heating_stage') || '0')[0], 10) || 0;
const slope = N('input_number.heating_slope'), offset = N('input_number.heating_offset');
const kp = N('input_number.heating_kp'), ki = N('input_number.heating_ki');
const floorH = N('input_number.heating_stage_floor');
const setDay = N('input_number.heating_setpoint_day'), setNight = N('input_number.heating_setpoint_night');
const preheat = N('input_number.heating_preheat_minutes'), hold = N('input_number.heating_alarm_hold_minutes');
const boostMin = N('input_number.heating_boost_minutes');
if ([slope, offset, kp, ki, floorH, setDay, setNight, preheat, hold, boostMin].some(v => v === null)) {
    node.status({ fill: 'red', shape: 'ring', text: 'heating helpers missing' });
    return null;
}
const eveStart = tmin('input_datetime.heating_weekday_evening_start', 960);
const endT = tmin('input_datetime.heating_period_end', 1350);
const wkndStart = tmin('input_datetime.heating_weekend_start', 540);

const st = flow.get('state', 'file') || {};
if (st.day !== dkey) { st.day = dkey; st.alarmToday = null; st.alarmLatest = null; st.burnerMin = 0; }

// --- Schedule ---
// Weekdays with an alarm: (alarm - preheat) to (alarm + hold), then evening to end.
// Weekends, and weekdays without an alarm: weekend start to end.
// Alarms today (04:00-10:00) across the phones, remembered after they have rung.
// The morning runs from (earliest - preheat) to (latest + hold).
let phoneOk = false;
for (const id of cfg.ent.nextAlarms) {
    const na = S(id);
    const naDate = na && !['unavailable', 'unknown'].includes(na) ? new Date(na) : null;
    if (!naDate || isNaN(naDate)) continue;
    phoneOk = true;
    if (naDate.toDateString() !== now.toDateString()) continue;
    const am = naDate.getHours() * 60 + naDate.getMinutes();
    if (am < 240 || am > 600) continue;
    if (st.alarmToday == null || am < st.alarmToday) st.alarmToday = am;
    if (st.alarmLatest == null || am > st.alarmLatest) st.alarmLatest = am;
}
let alarmMin = st.alarmToday;
let alarmEnd = st.alarmLatest != null ? st.alarmLatest : alarmMin;
// All phone sensors unavailable: assume 06:00 unless the alarm calendar has an entry now.
if (alarmMin == null && !phoneOk && !weekend && S(cfg.ent.alarmCal) !== 'on') { alarmMin = 360; alarmEnd = 360; }

const periods = (!weekend && alarmMin != null)
    ? [[alarmMin - preheat, alarmEnd + hold], [eveStart, endT]]
    : [[wkndStart, endT]];
const cur = periods.find(([a, b]) => minOfDay >= a && minOfDay < b);
const inPeriod = !!cur;
const boost = inPeriod && (minOfDay - cur[0]) < boostMin;
const comfortMode = S('timer.heating_comfort_mode') === 'active';
const set = (inPeriod || comfortMode) ? setDay : setNight;

// --- Inputs ---
const room = N(cfg.ent.room);
// Newest update from temperature or humidity: both come in the same BLU packet.
const updMs = id => (states[id] && states[id].last_updated ? new Date(states[id].last_updated).getTime() : -Infinity);
const roomAgeMin = (nowMs - Math.max(updMs(cfg.ent.room), updMs(cfg.ent.roomHumidity))) / 60000;
const roomOk = room !== null && roomAgeMin <= ROOM_STALE_MIN;
const outNow = N(cfg.ent.outdoor);
if (outNow !== null) st.lastOutdoor = outNow;          // Met Office down: hold the last value
const outdoor = st.lastOutdoor != null ? st.lastOutdoor : null;

const ebus = flow.get('ebus') || {};
const ev = n => (ebus[n] && nowMs - ebus[n].ts < 5 * 60000 ? ebus[n].v : null);
const dhw = ev('HwcDemand') === 'yes' || ev('HwcImpellorSwitch') === 'yes';
const ebusOk = flow.get('ebusOk') !== false;          // set by the eBUS watchdog
const flameV = ev('Flame');
const flame = flameV === 'on';
const modulation = parseFloat(ev('ModulationDesired'));
if (flame) st.burnerMin = (st.burnerMin || 0) + 1;

// --- Control law ---
const err = roomOk ? set - room : 0;
const curve = outdoor !== null ? set + slope * (set - outdoor) + offset : null;
let I = st.I || 0;
// Integral from Stage 1 only, while heating and the curve is in charge (anti-windup).
if (stage >= 1 && roomOk && st.demand && !dhw && !boost && !comfortMode && !(st.guard && st.guard.forced)) {
    I = clamp(I + ki * err, -5, 5);
}
if (stage === 0) I = 0;
st.I = I;
const flowRaw = curve !== null ? curve + kp * err + I : null;
const floor = stage === 0 ? cfg.flowMax : floorH;
const curveTarget = flowRaw !== null ? clamp(flowRaw, floor, cfg.flowMax) : null;

// --- Comfort guard (Stage 1+, only when the curve is limiting the flow) ---
st.guard = st.guard || { forced: false, belowSince: null };
let comfortEvent = null;
if (stage >= 1 && inPeriod && roomOk && !boost) {
    if (st.guard.forced) {
        if (room >= set - GUARD_RELEASE) st.guard = { forced: false, belowSince: null };
    } else if (room < set - GUARD_BELOW && !dhw && curveTarget !== null && curveTarget < cfg.flowMax - 0.5) {
        if (!st.guard.belowSince) st.guard.belowSince = nowMs;
        if (nowMs - st.guard.belowSince >= GUARD_MIN * 60000) {
            st.guard.forced = true;
            comfortEvent = { payload: { room: r1(room), set, stage, curveTarget: r1(curveTarget), at: now.toISOString() } };
        }
    } else {
        st.guard.belowSince = null;
    }
} else if (!inPeriod) {
    st.guard = { forced: false, belowSince: null };
}

// --- Final flow target ---
let target, why;
if (stage === 0) { target = cfg.flowMax; why = 'stage 0: panel ' + cfg.flowMax; }
else if (!ebusOk) { target = cfg.flowMax; why = 'eBUS down: panel ' + cfg.flowMax; }
else if (comfortMode) { target = cfg.flowMax; why = 'comfort mode'; }
else if (st.guard.forced) { target = cfg.flowMax; why = 'comfort guard'; }
else if (boost) { target = cfg.flowMax; why = 'warm-up boost'; }
else if (curveTarget === null) { target = st.lastTarget != null ? st.lastTarget : cfg.flowMax; why = 'no outdoor temp: holding'; }
else { target = curveTarget; why = 'curve'; }
target = r1(clamp(target, 20, cfg.flowMax));
st.lastTarget = target;

// --- Heat demand (relay), hysteresis on room temperature ---
let demand = !!st.demand;
if (!roomOk) demand = inPeriod || comfortMode; // no room sensor: behave like a timer
else if (comfortMode) demand = room < setDay + 1.0;   // "heat now", up to 1 °C above day set
else if (room < set - HYST) demand = true;
else if (room > set + HYST) demand = false;
st.demand = demand;

// --- Day statistics for the nightly review (global, file store) ---
const ds = global.get('heatingDay', 'file') || {};
ds.minutes = (ds.minutes || 0) + 1;
if (outdoor !== null) { ds.outSum = (ds.outSum || 0) + outdoor; ds.outN = (ds.outN || 0) + 1; }
if (demand) ds.demandMin = (ds.demandMin || 0) + 1;
if (flame) ds.burnerMin = (ds.burnerMin || 0) + 1;
if (inPeriod && !boost && roomOk && !dhw) {
    ds.occMin = (ds.occMin || 0) + 1;
    if (Math.abs(room - set) <= 0.5) ds.okMin = (ds.okMin || 0) + 1;
    if (room < set - 0.5) ds.shortMin = (ds.shortMin || 0) + 1;
}
if (comfortEvent) ds.comfortEvents = (ds.comfortEvents || 0) + 1;
global.set('heatingDay', ds, 'file');

// --- Outputs ---
const out = [];
const call = (action, entity_id, data) => out.push({ payload: { action, target: { entity_id }, data: data || {} } });
const setNum = (id, v, minDelta) => {
    if (v === null || !isFinite(v)) return;
    const c = N(id);
    if (c === null || Math.abs(c - v) >= minDelta) call('input_number.set_value', id, { value: v });
};
const setBool = (id, on) => { if (S(id) !== (on ? 'on' : 'off')) call(`input_boolean.turn_${on ? 'on' : 'off'}`, id); };

setNum('input_number.heating_flow_target', target, 0.1);
setNum('input_number.heating_flow_curve', flowRaw === null ? null : r1(clamp(flowRaw, 0, 100)), 0.1);
setNum('input_number.heating_integral', r2(I), 0.01);
setNum('input_number.heating_setpoint', set, 0.05);
setNum('input_number.heating_boiler_modulation', isFinite(modulation) ? modulation : null, 0.5);
setNum('input_number.heating_burner_minutes_today', st.burnerMin || 0, 1);
setBool('input_boolean.heating_demand', demand);
setBool('input_boolean.heating_period', inPeriod);
if (flameV !== null) setBool('input_boolean.heating_flame', flame);

const status = [
    `S${stage}`, live ? 'LIVE' : 'dry-run',
    inPeriod ? (boost ? 'period (boost)' : 'period') : 'setback',
    `set ${set}`, `room ${roomOk ? r1(room) : '?'}`, `out ${outdoor !== null ? r1(outdoor) : '?'}`,
    `curve ${flowRaw !== null ? r1(flowRaw) : '?'}`, `target ${target} (${why})`,
    `demand ${demand ? 'ON' : 'off'}`, dhw ? 'DHW' : '', ebusOk ? '' : 'eBUS DOWN',
].filter(Boolean).join(' | ');
if (S('input_text.heating_status') !== status.slice(0, 255)) call('input_text.set_value', 'input_text.heating_status', { value: status.slice(0, 255) });

// Relay: only when live. Re-sent every few minutes even when HA's state matches:
// after a Shelly reboot HA can show a stale state until the integration reconnects.
if (live) {
    const want = demand ? 'on' : 'off';
    if (S(cfg.ent.relay) !== want || nowMs - (st.relaySentMs || 0) >= RELAY_RESEND_MS) {
        call(`switch.turn_${want}`, cfg.ent.relay);
        st.relaySentMs = nowMs;
    }
}

// eBUS SetMode: only when live, Stage 1+, and enabled in config after verification.
// Fields: hcmode;flowtempdesired;hwctempdesired;hwcflowtempdesired;disablehc;
//         disablehwctapping;disablehwcload;remotecontrolhcpump;releasebackup;releasecooling
// (ign fields omitted). Hot water: boiler setting, both disable bits 0.
let ebusMsg = null;
if (live && stage >= 1 && ebusOk && cfg.ebusWriteEnabled) {
    if (st.lastSent !== target || nowMs - (st.lastSentMs || 0) >= RESEND_MS) {
        ebusMsg = { topic: `${cfg.ebusPrefix}/SetMode/set`, payload: `auto;${target};${cfg.hwcTemp};-;0;0;0;0;0;0` };
        st.lastSent = target; st.lastSentMs = nowMs;
    }
}

flow.set('state', st, 'file');
global.set('heatingCtl', { ts: nowMs, live });         // the heartbeat checks this
node.status({ fill: live ? 'green' : 'yellow', shape: demand ? 'dot' : 'ring', text: status.slice(0, 80) });
return [out, ebusMsg, comfortEvent];

// ebusd watchdog (every 60 s). eBUS is "down" when no FlowTemp has arrived for
// 10 min or ebusd reports no bus signal. While down, the control loop uses the
// panel's 60 °C and sends nothing over eBUS, so the boiler is in plain room-stat mode.
const cfg = global.get('heatingCfg');
const ha = global.get('homeassistant');
const states = ha && ha.homeAssistant && ha.homeAssistant.states;
if (!cfg || !states) return null;
const ebus = flow.get('ebus') || {};
const fresh = ebus.FlowTemp && Date.now() - ebus.FlowTemp.ts < 10 * 60000;
const sig = states['binary_sensor.heating_ebusd_global_signal'];
const ok = !!fresh && !(sig && sig.state === 'off');
const was = flow.get('ebusOk');
flow.set('ebusOk', ok);
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'eBUS ok' : 'eBUS DOWN' });
if (was === undefined || was === ok) return null;            // only on a change
const text = ok ? 'eBUS is back. Weather control resumes.'
    : 'eBUS lost (no bus signal, or no boiler data for 10 min). The boiler runs at its panel 60 °C; the relay keeps room control.';
const out = [];
for (const n of cfg.notifyAll) out.push({ payload: { action: n, target: {}, data: { title: 'Heating', message: text } } });
out.push({ payload: { action: 'logbook.log', target: {}, data: { name: 'Heating', message: text, entity_id: 'input_select.heating_stage' } } });
return [out];

// Heartbeat to the Shelly failsafe (every 60 s): KVS.Set "hb" over MQTT RPC.
// Sent only while HA is in live control and the control loop ran in the last 3 min,
// so a stuck Node-RED or dry-run hands the relay to the Shelly's own thermostat.
const cfg = global.get('heatingCfg');
const ctl = global.get('heatingCtl');
if (!cfg || !ctl || !ctl.live || Date.now() - ctl.ts > 3 * 60000) {
    node.status({ fill: 'yellow', shape: 'ring', text: ctl && !ctl.live ? 'not sent: dry-run' : 'not sent: control loop stale' });
    return null;
}
const now = Math.floor(Date.now() / 1000);
node.status({ fill: 'green', shape: 'dot', text: `sent ${new Date().toLocaleTimeString()}` });
return {
    topic: `${cfg.shellyTopic}/rpc`,
    payload: JSON.stringify({ id: now, src: 'nodered-heating', method: 'KVS.Set', params: { key: 'hb', value: now } }),
};

// Mirror the Shelly failsafe mode (retained MQTT) into HA; notify on changes.
const cfg = global.get('heatingCfg');
const mode = String(msg.payload);
const prev = flow.get('fsMode');
flow.set('fsMode', mode);
const out = [{ payload: { action: 'input_text.set_value', target: { entity_id: 'input_text.heating_failsafe_mode' }, data: { value: mode } } }];
if (prev !== undefined && prev !== mode && cfg) {
    const text = mode === 'ha' ? 'Shelly failsafe: HA is back in control.'
        : `Shelly failsafe active (${mode}): the Shelly is running the heating on its own.`;
    for (const n of cfg.notifyAll) out.push({ payload: { action: n, target: {}, data: { title: 'Heating', message: text } } });
    out.push({ payload: { action: 'logbook.log', target: {}, data: { name: 'Heating', message: text, entity_id: 'input_text.heating_failsafe_mode' } } });
}
node.status({ fill: mode === 'ha' ? 'green' : 'red', shape: 'dot', text: mode });
return [out];

// Comfort event: room more than 1 °C below set for 30 min with the curve in charge.
// Mark the day, drop back one stage (Stage 0 is the floor), reset the good-day counter, notify.
const cfg = global.get('heatingCfg');
const states = global.get('homeassistant').homeAssistant.states;
const S = id => (states[id] ? states[id].state : undefined);
const stage = parseInt(String(S('input_select.heating_stage') || '0')[0], 10) || 0;
const names = ['0 Shadow', '1 Capped', '2 Assisted', '3 Auto'];
const floors = { 1: 50, 2: 35, 3: 30 };   // floor after demotion into that stage
const e = msg.payload;
const out = [];
const call = (action, target, data) => out.push({ payload: { action, target, data: data || {} } });

call('input_boolean.turn_on', { entity_id: 'input_boolean.heating_comfort_event_today' });
let text = `Comfort event: room ${e.room} °C vs set ${e.set} °C (curve ${e.curveTarget} °C). Forcing 60 °C until within 0.3 °C.`;
if (stage > 0) {
    const ns = stage - 1;
    call('input_select.select_option', { entity_id: 'input_select.heating_stage' }, { option: names[ns] });
    if (ns > 0) call('input_number.set_value', { entity_id: 'input_number.heating_stage_floor' }, { value: floors[ns] });
    call('input_number.set_value', { entity_id: 'input_number.heating_good_days' }, { value: 0 });
    text += ` Demoted to Stage ${ns}; good-day counter reset.`;
}
call('input_text.set_value', { entity_id: 'input_text.heating_last_decision' }, { value: text.slice(0, 255) });
call('logbook.log', {}, { name: 'Heating', message: text, entity_id: 'input_select.heating_stage' });
for (const n of cfg.notifyAll) call(n, {}, { title: 'Heating: comfort event', message: text });
node.status({ fill: 'red', shape: 'dot', text: `comfort event ${new Date().toLocaleTimeString()}` });
return [out];

// Comfort-mode button: 60 °C flow (day setpoint) for 4 hours via timer.heating_comfort_mode.
const cfg = global.get('heatingCfg');
const out = [];
const call = (action, target, data) => out.push({ payload: { action, target, data: data || {} } });
call('timer.start', { entity_id: 'timer.heating_comfort_mode' }, { duration: '04:00:00' });
call('logbook.log', {}, { name: 'Heating', message: 'Comfort mode on: 60 °C for 4 hours', entity_id: 'timer.heating_comfort_mode' });
for (const n of cfg.notifyAll) call(n, {}, { title: 'Heating', message: 'Comfort mode on: 60 °C for 4 hours.' });
node.status({ fill: 'green', shape: 'dot', text: `on ${new Date().toLocaleTimeString()}` });
return [out];

// Nightly review, 03:00: daily stats -> learning per stage -> promotion check.
// Never promotes by itself: it asks for approval (notification + dashboard button).
const cfg = global.get('heatingCfg');
const states = global.get('homeassistant').homeAssistant.states;
const S = id => (states[id] ? states[id].state : undefined);
const N = id => { const v = parseFloat(S(id)); return isFinite(v) ? v : null; };
const r2 = v => Math.round(v * 100) / 100;

const ds = global.get('heatingDay', 'file') || {};
const h = global.get('heatingHistory', 'file') || { coldRun: 0, coldSnapPassed: false };
const stage = parseInt(String(S('input_select.heating_stage') || '0')[0], 10) || 0;
const live = S('input_boolean.heating_live') === 'on';
let good = N('input_number.heating_good_days') || 0;
let slope = N('input_number.heating_slope'), offset = N('input_number.heating_offset');
const floor = N('input_number.heating_stage_floor');

// --- Day summary ---
const meanOut = ds.outN ? ds.outSum / ds.outN : null;
const heatingDay = (ds.demandMin || 0) >= 60;
const comfort = (ds.comfortEvents || 0) > 0 || S('input_boolean.heating_comfort_event_today') === 'on';
const okFrac = ds.occMin ? (ds.okMin || 0) / ds.occMin : null;
const held = heatingDay && !comfort && okFrac !== null && okFrac >= 0.9 && (ds.shortMin || 0) < 30;
const short = heatingDay && (comfort || (ds.shortMin || 0) >= 30);
const summary = `day: heating ${heatingDay ? 'yes' : 'no'}, mean out ${meanOut !== null ? meanOut.toFixed(1) : '?'} °C, ` +
    `in band ${okFrac !== null ? Math.round(okFrac * 100) : '?'}%, short ${ds.shortMin || 0} min, ` +
    `burner ${ds.burnerMin || 0} min, comfort events ${ds.comfortEvents || 0}`;
const decisions = [];

// --- Good-day counter ---
if (stage === 0) { if (heatingDay && live) good += 1; }       // Stage 0: live heating days logged
else if (heatingDay) { good = held ? good + 1 : 0; }           // Stage 1+: consecutive good heating days

// --- Cold snap (Stage 1 exit): 2+ consecutive days with mean outdoor <= 2 °C, no comfort events ---
if (stage === 1) {
    if (meanOut !== null && meanOut <= 2 && heatingDay && !comfort) h.coldRun += 1;
    else if (comfort || (meanOut !== null && meanOut > 2)) h.coldRun = 0;
    if (h.coldRun >= 2 && !h.coldSnapPassed) { h.coldSnapPassed = true; decisions.push('cold snap passed'); }
}

// --- Learning ---
const slopeMax = stage === 3 ? 2.0 : 2.5, slopeMin = 0.8;
const raise = () => {
    if (meanOut !== null && meanOut < 5) { const n = Math.min(slopeMax, r2(slope + 0.1)); decisions.push(`short day (cold): slope ${slope} -> ${n}`); slope = n; }
    else { const n = Math.min(15, offset + 2); decisions.push(`short day (mild): offset ${offset} -> ${n}`); offset = n; }
};
if (stage === 1 && short) raise();                                   // raise-only
if (stage >= 2) {
    if (short) raise();
    else if (held) {
        if (offset > 0) { const n = Math.max(0, offset - 1); decisions.push(`held set: offset ${offset} -> ${n}`); offset = n; }
        else if (slope > slopeMin) { const n = Math.max(slopeMin, r2(slope - 0.05)); decisions.push(`held set: slope ${slope} -> ${n}`); slope = n; }
    }
}
if (stage === 3 && slope > 2.0) slope = 2.0;

// --- Promotion check ---
let pending = null;
if (stage === 0 && live && good >= 7) pending = { toStage: 1, floor: 50, text: 'Ready to move to Stage 1 (capped, floor 50 °C)' };
if (stage === 1 && good >= 7 && h.coldSnapPassed) pending = { toStage: 2, floor: 45, text: 'Ready to move to Stage 2 (assisted, floor 45 °C)' };
if (stage === 2 && good >= 7) pending = floor > 35
    ? { toStage: 2, floor: floor - 5, text: `Ready to lower the floor to ${floor - 5} °C (Stage 2)` }
    : { toStage: 3, floor: 30, text: 'Ready to move to Stage 3 (auto, floor 30 °C)' };
if (pending) { pending.created = Date.now(); decisions.push(pending.text + ' - waiting for approval'); }
global.set('heatingPending', pending, 'file');
global.set('heatingHistory', h, 'file');
global.set('heatingDay', {}, 'file');

// --- Outputs ---
const out = [];
const call = (action, target, data) => out.push({ payload: { action, target, data: data || {} } });
call('input_number.set_value', { entity_id: 'input_number.heating_good_days' }, { value: good });
if (slope !== N('input_number.heating_slope')) call('input_number.set_value', { entity_id: 'input_number.heating_slope' }, { value: slope });
if (offset !== N('input_number.heating_offset')) call('input_number.set_value', { entity_id: 'input_number.heating_offset' }, { value: offset });
call('input_boolean.turn_off', { entity_id: 'input_boolean.heating_comfort_event_today' });
const text = `Nightly S${stage}: ${decisions.length ? decisions.join('; ') : 'no change'}. Good days ${good}. ${summary}`;
call('input_text.set_value', { entity_id: 'input_text.heating_last_decision' }, { value: text.slice(0, 255) });
call('logbook.log', {}, { name: 'Heating', message: text, entity_id: 'input_select.heating_stage' });
if (pending) {
    call(cfg.notifyOwner, {}, {
        title: 'Heating', message: `${pending.text} - approve?`,
        data: { actions: [{ action: 'HEATING_PROMOTE', title: 'Approve' }, { action: 'HEATING_PROMOTE_NO', title: 'Not yet' }] },
    });
}
node.status({ text: `${new Date().toLocaleString()}: ${decisions.length} decision(s)` });
return [out];

// Promotion approval: notification "Approve" tap or the dashboard button.
// Only acts on a promotion the nightly review has offered in the last 24 h.
const cfg = global.get('heatingCfg');
const p = msg.payload || {};
const action = (p.data && p.data.action) || p.action;
const fromButton = msg.topic === 'button';
if (!fromButton && action !== 'HEATING_PROMOTE') return null;   // includes "Not yet"
const pending = global.get('heatingPending', 'file');
const out = [];
const call = (action, target, data) => out.push({ payload: { action, target, data: data || {} } });
if (!pending || Date.now() - pending.created > 24 * 3600 * 1000) {
    call(cfg.notifyOwner, {}, { title: 'Heating', message: 'No promotion is waiting for approval.' });
    return [out];
}
const names = ['0 Shadow', '1 Capped', '2 Assisted', '3 Auto'];
call('input_select.select_option', { entity_id: 'input_select.heating_stage' }, { option: names[pending.toStage] });
call('input_number.set_value', { entity_id: 'input_number.heating_stage_floor' }, { value: pending.floor });
call('input_number.set_value', { entity_id: 'input_number.heating_good_days' }, { value: 0 });
const text = `Approved: Stage ${pending.toStage}, floor ${pending.floor} °C.`;
call('input_text.set_value', { entity_id: 'input_text.heating_last_decision' }, { value: text });
call('logbook.log', {}, { name: 'Heating', message: text, entity_id: 'input_select.heating_stage' });
for (const n of cfg.notifyAll) call(n, {}, { title: 'Heating', message: text });
global.set('heatingPending', null, 'file');
node.status({ fill: 'green', shape: 'dot', text });
return [out];

// One-off: set the starting values. Press once after creating the helpers.
// Pressing it again resets learning (slope/offset) and the stage to Stage 0.
const out = [];
const call = (action, entity_id, data) => out.push({ payload: { action, target: { entity_id }, data } });
const nums = {
    heating_slope: 1.8, heating_offset: 5, heating_kp: 3, heating_ki: 0.02, heating_stage_floor: 50,
    heating_setpoint_day: 19.5, heating_setpoint_night: 16, heating_preheat_minutes: 60,
    heating_alarm_hold_minutes: 60, heating_boost_minutes: 45, heating_good_days: 0, heating_integral: 0,
};
for (const [k, v] of Object.entries(nums)) call('input_number.set_value', `input_number.${k}`, { value: v });
call('input_datetime.set_datetime', 'input_datetime.heating_weekday_evening_start', { time: '16:00:00' });
call('input_datetime.set_datetime', 'input_datetime.heating_period_end', { time: '22:30:00' });
call('input_datetime.set_datetime', 'input_datetime.heating_weekend_start', { time: '09:00:00' });
call('input_select.select_option', 'input_select.heating_stage', { option: '0 Shadow' });
call('input_boolean.turn_off', 'input_boolean.heating_live', {});
global.set('heatingHistory', { coldRun: 0, coldSnapPassed: false }, 'file');
global.set('heatingPending', null, 'file');
global.set('heatingDay', {}, 'file');
node.status({ fill: 'green', shape: 'dot', text: `set ${new Date().toLocaleString()}` });
return [out];
